import React, { useState, useContext } from 'react';
import { AuthContext } from '../context/AuthContext';
import { useHistory } from 'react-router-dom'; // Importar useHistory
import Header from '../components/header';
import HomeImg from "../imagenes/undraw_beach_day_cser.png";
import "./home.css";
import index from '../services/algolia'; // Asegurate que la ruta sea correcta

const Home = () => {
  const { user } = useContext(AuthContext);
  const userId = user?.id;
  console.log(userId);
  
  const history = useHistory(); // Inicializar useHistory

  const [ubicacion, setUbicacion] = useState(null);
  const [error, setError] = useState(null);
  const [resultados, setResultados] = useState([]);

  const obtenerUbicacion = () => {
    if (!navigator.geolocation) {
      setError('Geolocalización no soportada por el navegador');
      return;
    }

    navigator.geolocation.getCurrentPosition(
      (position) => {
        const { latitude, longitude } = position.coords;
        setUbicacion({ latitude, longitude });
        setError(null);

        buscarMascotasCercanas(latitude, longitude);

        if (!userId) {
          setError('Usuario no logueado');
          return;
        }

        fetch(`http://localhost:3000/api/users/${userId}`, {
          method: 'PUT',
          headers: {
            'Content-Type': 'application/json',
          },
          body: JSON.stringify({
            location: {
              latitude,
              longitude,
            },
          }),
        })
          .then(response => response.json())
          .then(data => {
            console.log('Ubicación actualizada:', data);
          })
          .catch(err => {
            console.error('Error al actualizar ubicación:', err);
            setError('Error al actualizar la ubicación en el servidor');
          });
      },
      () => {
        setError('No se pudo obtener la ubicación');
      }
    );
  };

  const buscarMascotasCercanas = async (latitude, longitude) => {
    try {
      const { hits } = await index.search('', {
        aroundLatLng: `${latitude},${longitude}`,
        aroundRadius: 5000, // 5 km de radio
      });
      setResultados(hits);
    } catch (error) {
      console.error('Error buscando mascotas:', error);
    }
  };

  // Función para manejar el clic en el botón "¿Cómo funciona Pet Finder?"
  const handleHowItWorksClick = () => {
    history.push('/how-it-works'); // Cambia la ruta según tu configuración
  };

  return (
    <div className='bodyHome'>
      <div className='contenedorHome'>
        <img src={HomeImg} alt="Logo" className='imagenHome'/>
        <h1 className='tituloHome'>Pet Finder App</h1>
        <p className='textoHome'>Encontrá y reportá mascotas perdidas cerca de tu ubicación</p>
      </div>
      <div className="contenedorboteneshome">
        <button className='botonUnoHome' onClick={obtenerUbicacion}>Dar mi ubicación actual</button>
        <button className='botonDosHome' onClick={handleHowItWorksClick}>¿Cómo funciona Pet Finder?</button>
      </div>
      {ubicacion && (
        <p>Ubicación: Latitud {ubicacion.latitude}, Longitud {ubicacion.longitude}</p>
      )}
      {error && <p style={{ color: 'red' }}>{error}</p>}
      {resultados.length > 0 && (
        <ul>
          {resultados.map((pet) => (
            <li key={pet.objectID}>{pet.name}</li>
          ))}
        </ul>
      )}
    </div>
  );
};

export default Home;
